from itertools import product

def level_table(max_depth: int = 12) -> list[tuple[int, int, int]]:
    """Compare enumerated counts with the formula 2^n."""
    return [(n, len(list(product((0, 1), repeat=n))), 2 ** n)
            for n in range(max_depth + 1)]

if __name__ == "__main__":
    for n, observed, predicted in level_table():
        print(f"{n:2d} {observed:5d} {predicted:5d}")

from itertools import product

Word = tuple[int, ...]

def is_edge(u: Word, v: Word) -> bool:
    return len(u) == len(v) and u[1:] == v[:-1]

def verify(max_length: int = 8) -> tuple[int, int]:
    tested = passed = 0
    for n in range(2, max_length + 1):
        words = list(product((0, 1), repeat=n))
        for u in words:
            for bit in (0, 1):
                v = u[1:] + (bit,)
                tested += 1
                passed += int(is_edge(u[:-1], v[:-1]))
    return tested, passed

if __name__ == "__main__":
    print("tested, passed =", verify())

from typing import Sequence

Word = tuple[int, ...]

def thread(sample: Sequence[int]) -> list[Word]:
    return [tuple(sample[:n]) for n in range(len(sample) + 1)]

def separation(a: Sequence[int], b: Sequence[int]) -> int | None:
    for k, (x, y) in enumerate(zip(a, b)):
        if x != y:
            return k + 1
    return None

if __name__ == "__main__":
    a, b = (0, 0, 1, 0, 1), (0, 0, 1, 1, 1)
    print("thread a:", thread(a))
    print("thread b:", thread(b))
    print("first separating level:", separation(a, b))

