from itertools import product

def binary_words(n: int) -> list[tuple[int, ...]]:
    """Return all 2^n binary words in lexicographic order."""
    if n < 0:
        raise ValueError("n must be nonnegative")
    return [tuple(w) for w in product((0, 1), repeat=n)]

from typing import Optional, Sequence

def first_separating_level(a: Sequence[int], b: Sequence[int]) -> Optional[int]:
    """Return k+1 for the first differing coordinate k, if sampled."""
    if any(x not in (0, 1) for x in (*a, *b)):
        raise ValueError("samples must be binary")
    for k, (x, y) in enumerate(zip(a, b)):
        if x != y:
            return k + 1
    if len(a) != len(b):
        return min(len(a), len(b)) + 1
    return None

