#!/usr/bin/env python3
import matplotlib.pyplot as plt
import networkx as nx
from itertools import product

def main(n: int = 3) -> None:
    words = ["".join(map(str, w)) for w in product((0, 1), repeat=n)]
    graph = nx.DiGraph()
    for word in words:
        for bit in "01": graph.add_edge(word, word[1:] + bit)
    pos = nx.circular_layout(graph)
    plt.figure(figsize=(8, 8))
    nx.draw_networkx(graph, pos, node_color="#dbeafe", edge_color="#64748b",
                     node_size=1500, arrowsize=16, font_weight="bold")
    plt.title(f"Binary de Bruijn Graph on Length-{n} Words")
    plt.axis("off"); plt.tight_layout(); plt.savefig("debruijn_graph.png", dpi=180)

if __name__ == "__main__": main()

